def transform(grid):
    h, w = len(grid), len(grid[0])

    def period_and_lines(axis):
        n, m = (h, w) if axis == 0 else (w, h)
        lines = [
            [grid[i][j] if axis == 0 else grid[j][i] for j in range(m)]
            for i in range(n)
        ]

        best_p, best_score = 1, -1
        for p in range(2, min(10, n)):
            sims, pairs = 0, 0
            for r in range(p):
                group = [lines[i] for i in range(r, n, p)]
                for a in range(len(group)):
                    for b in range(a):
                        sims += sum(x == y for x, y in zip(group[a], group[b])) / m
                        pairs += 1
            score = sims / pairs if pairs else 0
            if score > best_score + 0.025:
                best_p, best_score = p, score

        p = best_p
        best_r, best_uniformity = 0, -1
        for r in range(p):
            group = [lines[i] for i in range(r, n, p)]
            uniformity = 0
            for line in group:
                counts = {}
                for v in line:
                    counts[v] = counts.get(v, 0) + 1
                uniformity += max(counts.values()) / m
            uniformity /= max(1, len(group))
            if uniformity > best_uniformity:
                best_r, best_uniformity = r, uniformity
        return [i for i in range(n) if i % p == best_r]

    rows = period_and_lines(0)
    cols = period_and_lines(1)
    if len(rows) < 2 or len(cols) < 2:
        return [[0]]

    # Dominant interior/background color.
    rs, cs = set(rows), set(cols)
    counts = {}
    for i in range(h):
        if i not in rs:
            for j in range(w):
                if j not in cs:
                    v = grid[i][j]
                    counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get) if counts else 0

    # Marked crossings are intersections that differ from the usual line color.
    crossings = [[grid[r][c] for c in cols] for r in rows]
    line_counts = {}
    for row in crossings:
        for v in row:
            if v != background:
                line_counts[v] = line_counts.get(v, 0) + 1
    line_color = max(line_counts, key=line_counts.get) if line_counts else background

    active_r = [i for i, row in enumerate(crossings)
                if any(v != line_color for v in row)]
    active_c = [j for j in range(len(cols))
                if any(crossings[i][j] != line_color for i in range(len(rows)))]

    if len(active_r) >= 2:
        rows = rows[min(active_r):max(active_r) + 1]
    if len(active_c) >= 2:
        cols = cols[min(active_c):max(active_c) + 1]

    out = []
    for i in range(len(rows) - 1):
        row = []
        for j in range(len(cols) - 1):
            vals = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                    grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]]
            row.append(vals[0] if vals[0] != line_color and all(v == vals[0] for v in vals)
                       else background)
        out.append(row)
    return out
